import {WORKFLOW_STAGES,workflowStatus,reviewStage} from './timetable-workflow.mjs';
import {teacherSubjects,savePlanningTeacher,assignTeachingLoad,studentChoices,updateStudentChoices} from './timetable-manager-inputs.mjs';
import {studentById} from './model.mjs';

export function createTimetableManagerUI(ui){
 const {esc,options,button,getProject,save,open:openBase,closeDialog,navigate,render,toast}=ui;
 const open=(title,body,id)=>{openBase(title,body,id);const labels={'tt-manager-teacher-form':'Save teacher','tt-manager-subject-form':'Save subject','tt-manager-pick-student-form':'Open student choices','tt-manager-student-choices-form':'Save student choices','tt-manager-assignment-form':'Assign teaching load','tt-manager-generate-form':'Generate timetable'};const target=document.querySelector('[form="'+id+'"]');if(target&&labels[id])target.textContent=labels[id];};
 let lastProject=null,lastStatus=null;
 let checklist='subjects',selectedSubject='',selectedTeacher='',selectedSections=[],selectedRoom='',preview=null,editingTeacher=null,editingStudent=null;
 const href=id=>'#/timetable?tab='+id;
 const p=()=>getProject();
 const subjectName=id=>p().subjects.find(s=>s.id===id)?.name||id;
 const isManager=value=>value?.startsWith('tt-manager-');
 const go=id=>navigate(href(id));
 function refresh(control){const selectors=['.tm-section-choices','.tm-teacher-loads','.tm-checklist-rows','.tm-quick-assign form'],scrolls=selectors.map(selector=>[selector,document.querySelector(selector)?.scrollTop||0]),id=control?.id,section=control?.matches?.('[data-manager-section]')?control.value:null;render();const target=id?document.getElementById(id):section?[...document.querySelectorAll('[data-manager-section]')].find(el=>el.value===section):null;target?.focus({preventScroll:true});for(const [selector,top] of scrolls){const node=document.querySelector(selector);if(node)node.scrollTop=top;}}
 function status(report){const project=p();if(lastProject!==project){lastProject=project;lastStatus=workflowStatus(project,report);}return lastStatus;}
 function nav(report,active){const flow=status(report);return `<nav class="tt-tabs tm-stages" aria-label="Timetable manager workflow">${flow.stages.map((s,i)=>`<a href="${href(s.id)}" class="${active===s.id?'active ':''}${s.reviewed?'tm-reviewed ':''}${s.blockers.length?'tm-blocked':''}" ${active===s.id?'aria-current="page"':''}><span>${i+1}</span>${esc(s.title)}${s.reviewed?'<small>✓</small>':''}</a>`).join('')}</nav>`;}
 function reviewBar(tab,report){const flow=status(report),stage=flow.stages.find(s=>s.id===tab);if(!stage)return '';if(tab==='board')return `<div class="tm-review-bar"><span>${flow.preflight.canGenerate?'Generate and refine the draft. Input edits reopen the relevant reviews.':flow.preflight.blockers.length+' input blocker(s). Resolve these before generating.'}</span><a href="${href('checks')}">Review inputs</a></div>`;const next=WORKFLOW_STAGES[WORKFLOW_STAGES.findIndex(s=>s.id===tab)+1];return `<div class="tm-review-bar"><span>${stage.reviewed?'✓ Reviewed for the current inputs':stage.blockers.length?stage.blockers.length+' input issue(s) to resolve':'Review this stage before continuing'}</span><div>${button(stage.reviewed?'Reviewed':'Mark reviewed','tt-manager-review',`data-stage="${tab}" ${stage.reviewed||stage.blockers.length?'disabled':''}`,'small')}${next?button('Next: '+next.title,'tt-manager-go',`data-stage="${next.id}"`,'small'):''}</div></div>`;}
 function setup(report){const project=p(),flow=status(report),next=flow.stages.find(s=>!s.reviewed&&s.id!=='board')||flow.stages.at(-1);return `<section class="tm-overview"><div class="tm-start"><p class="eyebrow">TIMETABLE MANAGER</p><h2>Build the timetable from the inputs</h2><p>Collect Year 10 choices using Model 3, then review blocking, specialist staffing and school constraints. Work through data, student choices and teaching loads before generating the week.</p><div class="actions">${next.id==='setup'?button('Review school week','tt-edit-day','','primary small'):button('Continue: '+next.title,'tt-manager-go',`data-stage="${next.id}"`,'primary small')}${button('Start new planning draft','tt-scope','','small')}<a class="btn small" href="${href('board')}">Open plotting board</a></div></div><div class="tm-setup-columns"><section class="panel"><div class="panel-head"><h3>School week</h3>${button('Edit teaching day','tt-edit-day','','small')}</div><div class="panel-body"><dl><dt>Planning year</dt><dd>2026–27 demonstration</dd><dt>Option model</dt><dd>Model ${esc(project.demonstrationModel||'1')} · four lessons per selected subject</dd><dt>Teaching cycle</dt><dd>${project.days.length} days × ${project.periods.length} periods</dd><dt>Registration</dt><dd>08:15–08:30 · outside the teaching cycle</dd></dl><div class="tm-periods">${project.periods.map(r=>`<span><strong>P${esc(r.id)}</strong> ${r.start}–${r.end}</span>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h3>Manager route</h3></div><ol class="tm-route-list">${flow.stages.map((s,i)=>`<li><a href="${href(s.id)}"><strong>${i+1}. ${esc(s.title)}</strong><span>${s.reviewed?'Reviewed':s.blockers.length?s.blockers.length+' issue(s)':s.id==='board'?report.complete?'Complete draft':'Generate / refine':'To review'}</span></a></li>`).join('')}</ol></section></div><p class="tt-note">A new draft uses the existing fictional MIS people; lesson placements start empty except fixed assemblies. Planning edits stay separate from attendance and grades. Input reviews are WIST workflow aids; they do not prove that every lesson can be placed.</p></section>`;}
 function dataPage(kind,search){const project=p(),rows=project[kind].filter(r=>!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));return `<div class="tt-data-toolbar"><label>Data <select id="tt-data-kind">${options([['teachers','Teachers'],['groups','Sections'],['rooms','Rooms'],['subjects','Subjects'],['periods','Periods']],kind)}</select></label><input id="tt-search" type="search" aria-label="Search planning data" placeholder="Search planning data…" value="${esc(search)}">${kind==='teachers'?button('Add planning teacher','tt-manager-add-teacher','','primary small'):kind==='rooms'?button('Add room','tt-add-room','','primary small'):kind==='subjects'?button('Add planning subject','tt-manager-add-subject','','primary small'):kind==='periods'?button('Edit teaching day','tt-edit-day','','small'):''}</div><section class="panel tt-table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>${esc(kind)}</th><th>Planning details</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name||r.label)}</strong>${r.planningOnly?'<small>Planning only</small>':''}</td><td>${kind==='teachers'?esc(r.area||'Teaching')+'<small>'+esc(teacherSubjects(project,r.id).map(subjectName).join(', '))+'</small>':kind==='groups'?r.studentIds.length+' linked students':kind==='rooms'?esc(r.type)+' · '+r.capacity+' seats':kind==='periods'?r.start+'–'+r.end:project.activities.filter(a=>a.subjectId===r.id).length+' teaching groups'}</td><td>${['rooms','teachers','groups'].includes(kind)?button('Time off','tt-resource-off',`data-kind="${kind}" data-id="${esc(r.id)}"`,'small'):''}${kind==='teachers'?button('Edit teacher','tt-manager-edit-teacher',`data-id="${esc(r.id)}"`,'small'):kind==='rooms'?button('Edit room','tt-edit-room',`data-id="${esc(r.id)}"`,'small'):kind==='periods'?button('Edit times','tt-edit-day','','small'):''}</td></tr>`).join('')}</tbody></table></div></section><p class="tt-note">Teacher subjects declare planning eligibility. New planning teachers do not create MIS login accounts. Linked pupil identities are retained; student option choices are edited in the next stage.</p>`;}
 function load(t){const project=p(),activities=project.activities.filter(a=>a.teacherIds.includes(t.id)),required=(t.committedLoad||0)+activities.reduce((n,a)=>n+a.weeklyCount*a.duration,0),available=project.days.reduce((n,d)=>n+Math.min(project.constraints.maxTeacherDaily,project.periods.filter(r=>!t.blocked?.includes(d.id+'|'+r.id)).length),0),minutes=project.periods.reduce((n,r)=>n+(Number(r.end.slice(0,2))*60+Number(r.end.slice(3)))-(Number(r.start.slice(0,2))*60+Number(r.start.slice(3))),0)/project.periods.length;return {required,available:project.schoolPolicy?Math.min(available,['HOD','HOY'].includes(t.duty)?24:30):available,minutes,activities};}
 function matchedActivities(){return p().activities.filter(a=>a.subjectId===selectedSubject&&selectedSections.some(id=>a.groupIds.includes(id)));}
 function loads(){const project=p();if(!project.subjects.some(s=>s.id===selectedSubject))selectedSubject=project.subjects[0]?.id||'';const teachers=project.teachers.filter(t=>teacherSubjects(project,t.id).includes(selectedSubject));if(!teachers.some(t=>t.id===selectedTeacher))selectedTeacher=teachers[0]?.id||'';const candidateGroups=project.groups.filter(g=>project.activities.some(a=>a.subjectId===selectedSubject&&a.groupIds.includes(g.id)));selectedSections=selectedSections.filter(id=>candidateGroups.some(g=>g.id===id));const activities=matchedActivities(),roomIds=activities.length?project.rooms.filter(r=>activities.every(a=>a.roomIds.includes(r.id)&&r.capacity>=a.studentIds.length)):[];if(selectedRoom&&!roomIds.some(r=>r.id===selectedRoom))selectedRoom='';return `<div class="tm-load-workbench"><section class="tm-teacher-loads"><h2>Teacher loads</h2>${project.teachers.map(t=>{const l=load(t);return `<article class="${l.required>l.available?'over':''}"><strong>${esc(t.name)}</strong><small>${l.required} / ${l.available} periods · ~${Math.round(l.required*l.minutes)} / ${Math.round(l.available*l.minutes)} min</small><progress max="${Math.max(l.required,l.available,1)}" value="${l.required}"></progress><small>${l.required>l.available?'Over capacity':l.required===l.available?'Full allocation':'Capacity remaining'}</small>${button('View allocations','tt-manager-filter-teacher',`data-id="${esc(t.id)}"`,'small')}</article>`;}).join('')}</section><section class="panel tm-checklist"><div class="panel-head"><h2>Distribution checklist</h2><div>${button('Subjects','tt-manager-checklist',`data-kind="subjects"`,checklist==='subjects'?'active small':'small')}${button('Rooms','tt-manager-checklist',`data-kind="rooms"`,checklist==='rooms'?'active small':'small')}</div></div><div class="tm-checklist-rows">${(checklist==='subjects'?project.subjects:project.rooms).map(row=>{const list=project.activities.filter(a=>checklist==='subjects'?a.subjectId===row.id:a.roomIds.includes(row.id)),missing=list.filter(a=>!a.teacherIds.length||!a.roomIds.length);return `<article><strong>${esc(row.name)}</strong><small>${list.length} ${checklist==='subjects'?'teaching groups':'eligible groups'}${checklist==='subjects'?' · '+list.reduce((n,a)=>n+a.weeklyCount*a.duration,0)+' weekly periods':' · '+row.capacity+' seats'}</small><span class="${missing.length?'error':'muted'}">${missing.length?missing.length+' incomplete allocations':!list.length?'No teaching allocations yet':checklist==='subjects'?'Allocated · review staff capacity':'Review capacity and time off'}</span>${checklist==='subjects'?button('Assign this subject','tt-manager-subject',`data-id="${esc(row.id)}"`,'small'):button('Room time off','tt-resource-off',`data-kind="rooms" data-id="${esc(row.id)}"`,'small')}</article>`;}).join('')}</div></section><section class="panel tm-quick-assign"><div class="panel-head"><h2>Quick assign</h2></div><form id="tt-manager-preview-form"><label class="field"><span>Subject</span><select id="tt-manager-assign-subject">${options(project.subjects.map(s=>[s.id,s.name]),selectedSubject)}</select></label><label class="field"><span>Teacher eligible for this subject</span><select id="tt-manager-assign-teacher" ${teachers.length?'':'disabled'}>${options(teachers.map(t=>[t.id,t.name]),selectedTeacher)}</select></label><div class="field" role="group" aria-label="Sections to assign"><span>Section(s)</span><div class="tm-section-choices">${candidateGroups.map(g=>`<label><input type="checkbox" data-manager-section value="${g.id}" ${selectedSections.includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join('')||'<p>No teaching allocation for this subject.</p>'}</div></div><label class="field"><span>Room (optional)</span><select id="tt-manager-assign-room">${options([['','Keep existing eligible rooms'],...roomIds.map(r=>[r.id,r.name])],selectedRoom)}</select></label><p class="tt-note">Mixed sets keep their complete membership. Preview shows the exact groups affected before applying the load.</p></form><div class="tm-load-links"><button class="btn primary small tm-preview-submit" type="submit" form="tt-manager-preview-form" ${activities.length&&teachers.length?'':'disabled'}>Preview assignment (${activities.length} groups)</button>${button('Browse all teaching allocations','tt-manager-browse-loads','','small')}${button('New teaching activity','tt-add-activity','','small')}</div></section></div>`;}
 function validation(report){const flow=status(report);return `<section class="tm-validation"><div class="panel-head"><div><h2>Validate the inputs</h2><small>Input readiness is separate from placing every lesson.</small></div>${button('Review & generate','tt-manager-generate','','primary small')}</div><div class="tm-preflight-grid"><section><h3>${flow.preflight.blockers.length} input blockers</h3>${flow.preflight.blockers.map(i=>`<article class="tm-problem"><p>${esc(i.message)}</p>${button('Open '+(i.target||'data'),'tt-manager-go',`data-stage="${esc(i.target||'data')}"`,'small')}</article>`).join('')||'<p>No blocking input problems were found. The search may still leave lessons unplaced.</p>'}</section><section><h3>${flow.preflight.warnings.length} points to review</h3>${flow.preflight.warnings.slice(0,12).map(i=>`<p>${esc(i.message)}</p>`).join('')||'<p>Review the teacher loads and constraints before generation.</p>'}<p>${report.unplaced.length} lesson cards remain unassigned in the current draft.</p></section></div></section>`;}
 function teacherDialog(id){editingTeacher=id||null;const project=p(),teacher=project.teachers.find(t=>t.id===id),ids=teacher?teacherSubjects(project,id):[];open(teacher?'Edit planning teacher':'Add planning teacher',`<div class="form-grid"><label class="field"><span>Name</span><input name="name" required maxlength="100" value="${esc(teacher?.name||'')}"></label><label class="field"><span>Curriculum area</span><input name="area" required maxlength="100" value="${esc(teacher?.area||'')}"></label></div><div class="form-grid"><label class="field"><span>Responsibility</span><select name="duty">${options(['Teacher','HOD','HOY'],teacher?.duty||'Teacher')}</select></label><div class="field"><span>Eligible year bands</span>${['primary','lower','igcse','as','a2'].map(b=>`<label><input type="checkbox" name="yearBands" value="${b}" ${(teacher?.yearBands||['primary','lower','igcse','as','a2']).includes(b)?'checked':''}>${b}</label>`).join('')}</div></div><div class="field" role="group" aria-label="Eligible teaching subjects"><span>Eligible teaching subjects</span><div class="tt-checkbox-list">${project.subjects.map(s=>`<label><input type="checkbox" name="subjects" value="${s.id}" ${ids.includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')}</div></div><p class="tt-note">These are planning eligibility declarations. Existing MIS identity and login accounts are unchanged.</p>`,'tt-manager-teacher-form');}
 function pickStudent(){const project=p(),ids=project.groups.filter(g=>g.year===10||g.year===11).flatMap(g=>g.studentIds);if(!ids.length){toast('Choose a Secondary or Whole school planning scope first.');return;}open('Choose a student to edit options',`<label class="field"><span>Student</span><select name="student">${options(ids.map(id=>[id,(studentById(id)?.name||id)+' · '+(studentById(id)?.groupName||'')]),editingStudent||ids[0])}</select></label>`,'tt-manager-pick-student-form');}
 function choicesDialog(id){editingStudent=id;const project=p(),student=studentById(id),rows=studentChoices(project,id);open('Student choices · '+(student?.name||id),`<p>Model 1 · select one subject per block, including at least one science. English and mathematics stay in their existing teaching sets.</p><label class="tm-eligibility"><input type="checkbox" name="nonUzbek" ${project.optionEligibility?.[id]?.nonUzbek?'checked':''}> Fictional test student is eligible for options marked ** (not from Uzbekistan)</label><div class="tm-choice-grid">${rows.map(r=>`<label class="field"><span>Block ${r.letter}</span><select name="choice-${r.blockId}" ${['H','I'].includes(r.letter)?'disabled':''}>${options(r.choices.map(c=>[c.id,subjectName(c.subjectId)+(c.nonUzbekOnly?' **':'')]),r.selectedActivityId)}</select></label>`).join('')}</div><p class="tt-note">Changing a choice clears the affected option blocks’ unlocked placements so they can be rescheduled together. Locked blocks must be unlocked first.</p>`,'tt-manager-student-choices-form');}
 function previewAssignment(){const project=p(),activities=matchedActivities();if(!activities.length)throw Error('Choose at least one section.');preview={activityIds:activities.map(a=>a.id),teacherId:selectedTeacher,...(selectedRoom?{roomIds:[selectedRoom]}:{})};const projected=assignTeachingLoad(project,preview),teacher=project.teachers.find(t=>t.id===selectedTeacher),before=load(teacher),after=projected.activities.filter(a=>a.teacherIds.includes(selectedTeacher)).reduce((n,a)=>n+a.weeklyCount*a.duration,0);open('Preview teaching load assignment',`<p>Use <strong>${esc(project.teachers.find(t=>t.id===selectedTeacher)?.name||'')}</strong> as the sole teacher for ${activities.length} teaching groups.</p>${activities.some(a=>a.teacherIds.length>1)?'<p class="error">Quick Assign replaces all existing teachers in these groups, including co-teachers. Use the teaching allocation editor to retain team teaching.</p>':''}<p>Teacher load: ${before.required} → ${after} / ${before.available} available periods.</p><p>${Object.keys(project.placements).length-Object.keys(projected.placements).length} placed lesson cards will be unassigned for rescheduling.</p>${after>before.available?'<p class="error">This exceeds available teaching time. Redistribute the load before generation.</p>':''}<div class="tm-preview-list">${activities.map(a=>`<article><strong>${esc(a.name)}</strong><small>${a.studentIds.length} students · ${a.weeklyCount*a.duration} periods per week · ${esc(project.groups.filter(g=>a.groupIds.includes(g.id)).map(g=>g.name).join(', '))}</small><small>Current teacher(s): ${esc(a.teacherIds.map(id=>project.teachers.find(t=>t.id===id)?.name||id).join(', '))}</small></article>`).join('')}</div><p class="tt-note">The full mixed-set memberships are retained. Affected unlocked placements, including their parallel option partners, are cleared for rescheduling.</p>`,'tt-manager-assignment-form');}
 function generateDialog(){const report=ui.report(),flow=status(report);open('Review before generating',`<p>${flow.preflight.canGenerate?'The input checks allow a scheduling attempt.':'Resolve the blocking inputs before generating.'} ${report.placed}/${report.total} cards are currently placed.</p>${flow.preflight.blockers.map(i=>'<p class="error">'+esc(i.message)+'</p>').join('')}<p>${flow.stages.filter(s=>s.id!=='board'&&!s.reviewed).length} input stages have not been reviewed for their current data.</p><p>Locked lessons are retained. A better valid existing draft is kept if the bounded search cannot improve it. Unplaced lessons remain visible; generation does not guarantee a finished timetable.</p>`,'tt-manager-generate-form');const submitButton=document.querySelector('[form="tt-manager-generate-form"]');submitButton.textContent='Generate timetable';submitButton.disabled=!flow.preflight.canGenerate;}
 function action(name,a){if(!isManager(name))return false;try{if(ui.busy()){toast('Cancel generation before editing the planning inputs.');return true;}switch(name){case'tt-manager-go':go(a.dataset.stage);break;case'tt-manager-review':save(reviewStage(p(),a.dataset.stage),'Stage reviewed for the current inputs.');break;case'tt-manager-add-teacher':teacherDialog();break;case'tt-manager-edit-teacher':teacherDialog(a.dataset.id);break;case'tt-manager-add-subject':open('Add planning subject','<label class="field"><span>Subject name</span><input name="name" required maxlength="80"></label><p class="tt-note">This adds a planning subject for teaching allocations. Model 1 choices remain fixed.</p>','tt-manager-subject-form');break;case'tt-manager-pick-student':pickStudent();break;case'tt-manager-checklist':checklist=a.dataset.kind;refresh();break;case'tt-manager-subject':selectedSubject=a.dataset.id;selectedSections=[];preview=null;refresh();break;case'tt-manager-workbench':ui.showWorkbench();break;case'tt-manager-browse-loads':ui.showAllocations();break;case'tt-manager-filter-teacher':ui.showAllocations(a.dataset.id);break;case'tt-manager-generate':generateDialog();break;}}catch(error){toast(error.message);}return true;}
 function change(t){if(!isManager(t.id)&&!t.matches?.('[data-manager-section]'))return false;preview=null;if(t.id==='tt-manager-assign-subject'){selectedSubject=t.value;selectedSections=[];}if(t.id==='tt-manager-assign-teacher')selectedTeacher=t.value;if(t.id==='tt-manager-assign-room')selectedRoom=t.value;if(t.matches('[data-manager-section]'))selectedSections=[...document.querySelectorAll('[data-manager-section]:checked')].map(el=>el.value);refresh(t);return true;}
 function submit(form){if(!isManager(form.id))return false;const d=new FormData(form);try{if(ui.busy())throw Error('Cancel generation before changing inputs.');if(form.id==='tt-manager-preview-form'){previewAssignment();return true;}if(form.id==='tt-manager-pick-student-form'){choicesDialog(d.get('student'));return true;}if(form.id==='tt-manager-generate-form'){if(!status(ui.report()).preflight.canGenerate)throw Error('Resolve the input blockers first.');closeDialog(true);go('board');ui.generate();return true;}let next;if(form.id==='tt-manager-teacher-form')next=savePlanningTeacher(p(),{id:editingTeacher,name:d.get('name'),area:d.get('area'),subjectIds:d.getAll('subjects'),duty:d.get('duty'),yearBands:d.getAll('yearBands')});else if(form.id==='tt-manager-assignment-form'){if(!preview)throw Error('Preview the assignment again.');next=assignTeachingLoad(p(),preview);}else if(form.id==='tt-manager-student-choices-form'){const choices=Object.fromEntries([...d.entries()].filter(([key])=>key.startsWith('choice-')).map(([key,value])=>[key.slice(7),value]));next=updateStudentChoices(p(),{studentId:editingStudent,choices,nonUzbek:d.has('nonUzbek')});}else if(form.id==='tt-manager-subject-form'){const name=d.get('name').trim();if(!name)throw Error('Enter a subject name.');if(p().subjects.some(s=>s.name.toLowerCase()===name.toLowerCase()))throw Error('That subject already exists.');next=structuredClone(p());next.subjects.push({id:'plan-subject-'+crypto.randomUUID(),name,color:'#487e64',planningOnly:true});}if(next){save(next,'Planning inputs saved; affected reviews and placements are rechecked.');closeDialog(true);}}catch(error){const target=form.querySelector('#tt-form-error')||form.querySelector('.error');const message=form.id==='tt-manager-student-choices-form'&&editingStudent?error.message.replaceAll(editingStudent,studentById(editingStudent)?.name||'this student'):error.message;if(target)target.textContent=message;else toast(message);}return true;}
 return{nav,reviewBar,setup,dataPage,loads,validation,action,change,submit,generateDialog,status};
}
